###############################################################
# 4. ROBUST HELPER FUNCTIONS (NA-PREVENTATIVE & CALIBRATED)
###############################################################

MAX_RETURN_CAP <- 0.50  # Cap extreme return distortions (+/- 50% per month)

safe_mean <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  mean(x)
}

safe_sd <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) < 2) return(NA_real_)
  sd(x)
}

# Robust Cumulative Compounded Return with log compounding
safe_cumulative_return <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  x_capped <- pmax(pmin(x, MAX_RETURN_CAP), -MAX_RETURN_CAP)
  mult <- pmax(1 + x_capped, 1e-6)
  exp(sum(log(mult))) - 1
}

# Annualized return from total compounded return
safe_annualized_return <- function(x) {
  x <- x[is.finite(x)]
  n <- length(x)
  if (n < 2) return(NA_real_)
  cum_ret <- safe_cumulative_return(x)
  if (!is.finite(cum_ret) || cum_ret <= -1) return(-1.0)
  (1 + cum_ret)^(12 / n) - 1
}

# Robust Peak-to-Trough Maximum Drawdown
safe_max_drawdown <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  x_capped <- pmax(pmin(x, MAX_RETURN_CAP), -MAX_RETURN_CAP)
  wealth <- cumprod(pmax(1 + x_capped, 1e-6))
  running_max <- cummax(wealth)
  drawdown <- (wealth - running_max) / running_max
  min(drawdown, na.rm = TRUE)
}

# Calibrated Sharpe Ratio (Excess return over RiskFree with small-sample regularization)
safe_calibrated_sharpe <- function(r, rf, eps = 1e-4) {
  valid <- is.finite(r) & is.finite(rf)
  if (sum(valid) < 2) return(NA_real_)
  
  r_valid  <- pmax(pmin(r[valid], MAX_RETURN_CAP), -MAX_RETURN_CAP)
  rf_valid <- rf[valid]
  
  excess <- r_valid - rf_valid
  mean_excess <- mean(excess, na.rm = TRUE)
  sd_excess <- sd(excess, na.rm = TRUE)
  
  if (is.na(sd_excess)) return(NA_real_)
  
  # Volatility regularization prevents near-zero denominator explosion (e.g. Fixed Short)
  sd_reg <- sqrt(sd_excess^2 + eps^2)
  (mean_excess / sd_reg) * sqrt(12)
}

safe_hit_rate <- function(expected, realized) {
  keep <- is.finite(expected) & is.finite(realized)
  exp_k <- expected[keep]
  real_k <- realized[keep]
  if (length(exp_k) == 0) return(NA_real_)
  mean(sign(exp_k) == sign(real_k))
}

safe_rank <- function(x, decreasing = TRUE) {
  output <- rep(NA_real_, length(x))
  valid  <- is.finite(x)
  if (!any(valid)) return(output)
  if (decreasing) {
    output[valid] <- rank(-x[valid], ties.method = "min")
  } else {
    output[valid] <- rank(x[valid], ties.method = "min")
  }
  output
}


