    # Cumulative & Annualized Returns (Compounded)
    CumulativeGrossReturn     = safe_cumulative_return(SelectedRealizedReturn),
    CumulativeNetReturn       = safe_cumulative_return(NetRealizedReturn),
    AnnualizedNetReturn       = safe_annualized_return(NetRealizedReturn),
    
    # Volatility Separation: Total vs. Excess (Reviewer 2, Bullet 5)
    TotalVol_Monthly          = safe_sd(NetRealizedReturn),
    TotalVol_Annualized       = safe_sd(NetRealizedReturn) * sqrt(12),
    ExcessVol_Monthly         = safe_sd(NetRealizedReturn - RiskFreeMonthly),
    ExcessVol_Annualized      = safe_sd(NetRealizedReturn - RiskFreeMonthly) * sqrt(12),
    
